        var e = propMap[toolId];
        uniforms[looksUniformName(e.enable)] = { type: "f", value: 1 };
        Object.keys(e.params).forEach(function (k) {
            uniforms[looksUniformName(e.params[k])] = { type: "f", value: 0 };
