// Per-channel curves table: entries are bytes of the composed channel curves.
function looksFillBytes(bytes, luts, sc) {
    for (var i = 0; i < LOOKS_LUT_SIZE; i++) {
        if (luts) {
            bytes[i * 3] = Math.round(Looks.color.clamp(luts.Red[i], 0, 1) * 255);
